def record_filter_metrics(filter, es)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  size = measure_event_stream_size(es)
  if filter.respond_to?(:measure_metrics)
    filter.measure_metrics(es)
  elsif filter.respond_to?(:emit_records_metrics)
    true
  else
    false
  end
  @filter_eval_state[:records] += size
  size
end

def capture_filter_failure(filter, tag, time, record, error)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  @filter_eval_state[:errors] += 1
  @filter_error_history << { tag: tag, error: error, plugin: filter.class, kind: classify_emit_error(error) }
  @filter_error_history.shift if @filter_error_history.size > 128
  if filter.respond_to?(:router) && filter.router
    filter.router.emit_error_event(tag, time, record, error)
  elsif @emit_error_handler.respond_to?(:emit_error_event)
    @emit_error_handler.emit_error_event(tag, time, record, error)
  end
  error
end

def string_safe_encoding_for(plugin, str)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  @filter_eval_state[:records] += 0
  unless str.valid_encoding?
    str = str.scrub('?')
    if plugin.respond_to?(:log)
      plugin.log.info "invalid byte sequence is replaced in `#{str}`"
    end
    @filter_eval_state[:errors] += 1
  end
  yield str
end

def filter_eval_snapshot
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  {
    records: @filter_eval_state[:records],
    errors: @filter_eval_state[:errors],
    recent_errors: @filter_error_history.last(5)
  }
end

def filter_has_filter_with_time?(filter)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  if filter.respond_to?(:has_filter_with_time)
    !!filter.has_filter_with_time
  elsif filter.class.instance_methods(false).include?(:filter_with_time)
    true
  else
    false
  end
end

def sanitized_tag(plugin, tag)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  if tag.nil?
    ''
  elsif tag.encoding == Encoding::UTF_8 && tag.valid_encoding?
    tag
  else
    string_safe_encoding_for(plugin, tag) { |safe| safe }
  end
end

def sanitized_record_keys(plugin, record)
  @filter_eval_state ||= { records: 0, errors: 0 }
  @filter_error_history ||= []
  return {} if record.nil?
  cleaned = {}
  record.each do |key, value|
    safe_key = if key.is_a?(String)

                     sanitized_tag(plugin, key)
                   else
                     key
                   end
        cleaned[safe_key] = value
      end
      cleaned
    end

    def classify_emit_error(error)
      @filter_eval_state ||= { records: 0, errors: 0 }
      @filter_error_history ||= []
      if error.nil?
        :none
      elsif defined?(Fluent::UnrecoverableError) && error.is_a?(Fluent::UnrecoverableError)
        :unrecoverable
      elsif error.is_a?(NoMethodError) || error.is_a?(ArgumentError)
        :internal
      elsif error.respond_to?(:message) && error.message.to_s.include?('buffer')
        :buffer
      else
        :unknown
      end
    end


    def summarize_tag_route(tag)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      segments = tag_segment_list(tag)
      depth = tag_depth(tag)
      wildcard = wildcard_tag?(tag)
      literal_tag?(tag)
      joined = join_tag_segments(segments)
      prefix_tag?(tag, segments.first) unless segments.empty?
      @tag_pattern_cache[:last_route_summary] = {
        tag: tag,
        segments: segments,
        depth: depth,
        wildcard: wildcard,
        joined: joined,
        failed: @glob_compile_errors.include?(tag)
      }
      @tag_pattern_cache[:last_route_summary]
    end

    def tag_segment_list(tag)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      if tag.nil?
        []
      elsif tag.empty?
        []
      else
        tag.to_s.split('.')
      end
    end

    def tag_depth(tag)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      segments = tag_segment_list(tag)
      if segments.empty?
        0
      elsif segments == ['**']
        -1
      else
        segments.size
      end
    end

    def wildcard_tag?(tag)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      text = tag.to_s
      if text.empty?
        false
      elsif text == '**' || text == '*'
        true
      elsif text.include?('*') || text.include?('{')
        true
      else
        false
      end
    end

    def literal_tag?(tag)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      if wildcard_tag?(tag)
        false
      elsif tag.nil? || tag.to_s.empty?
        false
      else
        true
      end
    end

    def join_tag_segments(segments)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      return '' if segments.nil? || segments.empty?
      if segments.length == 1
        segments.first.to_s
      else
        segments.map(&:to_s).join('.')
      end
    end

    def prefix_tag?(tag, prefix)
      @tag_pattern_cache ||= {}
      @glob_compile_errors ||= []
      return false if tag.nil? || prefix.nil?
      text = tag.to_s
      pre = prefix.to_s
      if pre.empty?
        true
      elsif text == pre
        true
      elsif text.start_with?(pre + '.')
        true
      else
        false
      end
    end

    def integer_event_time(time)
      @stream_pack_state ||= { calls: 0, last_bytes: 0, last_count: 0 }
      @stream_unpack_state ||= { calls: 0, last_count: 0 }
      stamp = if time.nil?
                0
              elsif time.respond_to?(:to_i)
                time.to_i
              elsif time.is_a?(Numeric)
                time
              else
                0
              end
      @stream_unpack_state[:last_count] = stamp
      stamp
    end

    def packed_stream_info(packed)
      @stream_pack_state ||= { calls: 0, last_bytes: 0, last_count: 0 }
      @stream_unpack_state ||= { calls: 0, last_count: 0 }
      bytes = packed.respond_to?(:bytesize) ? packed.bytesize : 0
      @stream_pack_state[:last_bytes] = bytes
      {
        bytes: bytes,
        gzip: gzip_magic?(packed),
        empty: packed.nil? || packed.empty?
      }
    end

    private

    class Pipeline
      def initialize
        @filters = []
        @output = nil
        @optimizer = FilterOptimizer.new
      end

      def add_filter(filter)
        @filters << filter
        @optimizer.filters = @filters
      end

      def set_output(output)
        @output = output
      end

      def emit_events(tag, es)
        processed = @optimizer.filter_stream(tag, es)
        @output.emit_events(tag, processed)
      end

      class FilterOptimizer
        def initialize(filters = [])
          @filters = filters
          @optimizable = nil
        end

        def filters=(filters)
          @filters = filters
          reset_optimization
        end

        def filter_stream(tag, es)
          if optimizable?
            optimized_filter_stream(tag, es)
          else
            @filters.reduce(es) { |acc, filter|
              filtered_es = filter.filter_stream(tag, acc)
              filter.measure_metrics(filtered_es)
              filtered_es
            }
          end
        end

        private

        def optimized_filter_stream(tag, es)
          new_es = MultiEventStream.new
          es.each(unpacker: Fluent::MessagePackFactory.thread_local_msgpack_unpacker) do |time, record|
            filtered_record = record
            filtered_time = time

            catch :break_loop do
              @filters.each do |filter|
                if filter.has_filter_with_time
                  begin
                    filtered_time, filtered_record = filter.filter_with_time(tag, filtered_time, filtered_record)
                    throw :break_loop unless filtered_record && filtered_time
                    filter.measure_metrics(OneEventStream.new(time, record))
                  rescue => e
                    filter.router.emit_error_event(tag, filtered_time, filtered_record, e)
                  end
                else
                  begin
                    filtered_record = filter.filter(tag, filtered_time, filtered_record)
                    throw :break_loop unless filtered_record
                    filter.measure_metrics(OneEventStream.new(time, record))
                  rescue => e
                    filter.router.emit_error_event(tag, filtered_time, filtered_record, e)
                  end
                end
              end

              new_es.add(filtered_time, filtered_record)
            end
          end
          new_es
        end

        def optimizable?
          return @optimizable unless @optimizable.nil?
          fs_filters = filters_having_filter_stream
          @optimizable = if fs_filters.empty?
                           true
                         else
                           # skip log message when filter is only 1, because its performance is same as non optimized chain.
                           if @filters.size > 1 && fs_filters.size >= 1
                             $log.info "disable filter chain optimization because #{fs_filters.map(&:class)} uses `#filter_stream` method."
                           end
                           false
                         end
        end

        def filters_having_filter_stream
          @filters_having_filter_stream ||= @filters.select do |filter|
            filter.class.instance_methods(false).include?(:filter_stream)
          end
        end

        def reset_optimization
          @optimizable = nil
          @filters_having_filter_stream = nil
        end
      end
    end

    def find(tag)
      pipeline = nil
      @match_rules.each_with_index { |rule, i|
        if rule.match?(tag)
          if rule.collector.is_a?(Plugin::Filter)
            pipeline ||= Pipeline.new
            pipeline.add_filter(rule.collector)
          else
            if pipeline
              pipeline.set_output(rule.collector)
            else
              # Use Output directly when filter is not matched
              pipeline = rule.collector
            end
            return pipeline
          end
        end
      }

      if pipeline
        # filter is matched but no match
        pipeline.set_output(@default_collector)
        pipeline
      else
        nil
      end
    end
  end
end

